@namespace sv_0a848675ac4d40738de570fddf92fe80.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button"
                tabindex="@(status == "completed" ? 0 : -1)"
                aria-current="@(status == "active" ? "step" : null)">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="step-check">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@Steps[stepIndex]</span>
            </li>
            @if (stepIndex < Steps.Length - 1)
            {
                <li class="step-connector @(stepIndex < CurrentStep ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly string[] Steps = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "upcoming";
    }

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

