@namespace sv_0a848675ac4d40738de570fddf92fe80.Components.Pages.Apply

@using sv_0a848675ac4d40738de570fddf92fe80.Models

<EditForm Model="Model" OnValidSubmit="HandleValidSubmit">
    <DataAnnotationsValidator />

    <h3>Personal Information</h3>

    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <InputText class="form-control" @bind-Value="Model.FullName" />
        <ValidationMessage For="() => Model.FullName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email *</label>
        <InputText class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="() => Model.Email" />
        @if (!string.IsNullOrEmpty(emailError))
        {
            <div class="text-danger mt-1">@emailError</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <InputText class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address *</label>
        <InputTextArea class="form-control" @bind-Value="Model.Address" rows="2" />
        <ValidationMessage For="() => Model.Address" />
    </div>

    <div class="step-buttons">
        <span></span>
        <button type="submit" class="btn btn-primary" disabled="@isValidating">
            @(isValidating ? "Validating..." : "Next →")
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? emailError;
    private bool isValidating;

    private async Task HandleValidSubmit()
    {
        emailError = null;
        isValidating = true;

        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                emailError = "This email address could not be verified.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }
}

@namespace sv_0a848675ac4d40738de570fddf92fe80.Components.Pages.Apply

@using sv_0a848675ac4d40738de570fddf92fe80.Models

<EditForm Model="this" OnValidSubmit="HandleValidSubmit">
    <ObjectGraphDataAnnotationsValidator />

    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button type="submit" class="btn btn-primary">Next →</button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleValidSubmit() => await OnNext.InvokeAsync();
}

@namespace sv_0a848675ac4d40738de570fddf92fe80.Components.Pages.Apply

@using sv_0a848675ac4d40738de570fddf92fe80.Models

<EditForm Model="this" OnValidSubmit="HandleValidSubmit">
    <ObjectGraphDataAnnotationsValidator />

    <h3>References</h3>
    <p class="text-muted">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]"
                       Index="index"
                       ShowRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button type="submit" class="btn btn-primary">Next →</button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private void AddReference() { if (References.Count < 3) References.Add(new ReferenceModel()); }
    private void RemoveReference(int index) { if (References.Count > 2) References.RemoveAt(index); }

    private async Task HandleValidSubmit() => await OnNext.InvokeAsync();
}

@namespace sv_0a848675ac4d40738de570fddf92fe80.Components.Pages.Apply

<h3>Cover Letter</h3>

<div class="mb-3">
    <label class="form-label">Write your cover letter below:</label>
    <textarea class="form-control" rows="12" maxlength="@MaxLength"
              @bind="CoverLetter" @bind:event="oninput"
              @bind:after="NotifyChanged"></textarea>
    <div class="form-text text-end">
        @(CoverLetter?.Length ?? 0) / @MaxLength characters
    </div>
</div>

<div class="step-buttons">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button type="button" class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private async Task NotifyChanged() => await CoverLetterChanged.InvokeAsync(CoverLetter);
}

@namespace sv_0a848675ac4d40738de570fddf92fe80.Components.Pages.Apply

@using sv_0a848675ac4d40738de570fddf92fe80.Models

<h3>Review &amp; Submit</h3>

@if (IsSubmitted)
{
    <div class="alert alert-success text-center p-4">
        <h4 class="mb-2">✓ Application Submitted!</h4>
        <p>Your application has been received. Your application ID is:</p>
        <p class="fs-3 fw-bold">@ApplicationId</p>
    </div>
}
else
{
    <div class="review-section">
        <div class="review-header">
            <h4>Personal Information</h4>
            <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
        </div>
        <dl class="row">
            <dt class="col-sm-3">Name</dt>
