}", "new_str": "<h3>Work History</h3>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <EditForm Model="Entries[index]" id="@($"work-entry-{index}")">
        <DataAnnotationsValidator />
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    </EditForm>
}

@if (validationErrors.Count > 0)
{
    <div class="alert alert-danger">
        @foreach (var error in validationErrors)
        {
            <div>@error</div>
        }
    </div>
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="step-buttons">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button type="button" class="btn btn-primary" @onclick="TryNext">Next →</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<string> validationErrors = [];

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task TryNext()
    {
        validationErrors.Clear();
        for (int i = 0; i < Entries.Count; i++)
        {
            var ctx = new ValidationContext(Entries[i]);
            var results = new List<ValidationResult>();
            if (!Validator.TryValidateObject(Entries[i], ctx, results, true))
            {
                validationErrors.AddRange(results.Select(r => $"Position {i + 1}: {r.ErrorMessage}"));
            }
        }

        if (validationErrors.Count == 0)
            await OnNext.InvokeAsync();
    }
}", "path": "/tmp/sv-0a848675ac4d40738de570fddf92fe80/Components/Pages/Apply/WorkHistoryStep.razor"}

